  8854  /* Formatting ofpacts. */
  8855
  8856  static void
  8857  ofpact_format(const struct ofpact *a,
  8858                const struct ofpact_format_params *fp)
  8859  {
  8860      switch (a->type) {
  8861  #define OFPACT(ENUM, STRUCT, MEMBER, NAME)                              \
  8862          case OFPACT_##ENUM:                                             \
  8863              format_##ENUM(ALIGNED_CAST(const struct STRUCT *, a), fp);  \
  8864              break;
  8865          OFPACTS
  8866  #undef OFPACT
  8867      default:
  8868          OVS_NOT_REACHED();
  8869      }
  8870  }
