  8872  /* Appends a string representing the 'ofpacts_len' bytes of ofpacts in
  8873   * 'ofpacts' to 'fp->s'.  If 'port_map' is nonnull, uses it to translate port
  8874   * numbers to names in output. */
  8875  void
  8876  ofpacts_format(const struct ofpact *ofpacts, size_t ofpacts_len,
  8877                 const struct ofpact_format_params *fp)
  8878  {
  8879      if (!ofpacts_len) {
  8880          ds_put_format(fp->s, "%sdrop%s", colors.drop, colors.end);
  8881      } else {
  8882          const struct ofpact *a;
  8883
  8884          OFPACT_FOR_EACH (a, ofpacts, ofpacts_len) {
  8885              if (a != ofpacts) {
  8886                  ds_put_char(fp->s, ',');
  8887              }
  8888
  8889              ofpact_format(a, fp);
  8890          }
  8891      }
  8892  }
